 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

+/** Picks a supported language (`ko` or `en`) from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const def = LANGUAGES.includes(fallback) ? fallback : "en";
+  if (typeof header !== "string" || !header.trim()) return def;
+  const parsed = header
+    .split(",")
+    .map((part, idx) => {
+      const [rawTag, ...params] = part.trim().split(";");
+      const lang = rawTag.trim().split(/[-_]/)[0].toLowerCase();
+      let q = 1;
+      for (const p of params) {
+        const [k, v] = p.split("=").map((s) => s.trim());
+        if (k.toLowerCase() === "q") {
+          q = Number(v);
+        }
+      }
+      return { lang, q, idx };
+    })
+    .filter((e) => Number.isFinite(e.q) && e.q > 0 && e.q <= 1 && LANGUAGES.includes(e.lang))
+    .sort((a, b) => b.q - a.q || a.idx - b.idx);
+  return parsed.length > 0 ? parsed[0].lang : def;
+}
